  changeDetailQty(n){this.state.qty=Math.max(1,this.state.qty+n);document.getElementById('detail-qty').textContent=this.state.qty},
  ratingLabel(id){const list=this.state.reviews[id]||[],n=list.length?Math.round(list.reduce((a,r)=>a+r.rating,0)/list.length):0;return list.length?`${String.fromCharCode(9733)} ${(list.reduce((a,r)=>a+r.rating,0)/list.length).toFixed(1)} ? ${list.length} ulasan`:'Belum ada ulasan'},
