  addToCart(){if(!this.state.user){this.requireSignIn();return}if(!this.state.size)return this.toast('Pilih ukuran terlebih dahulu.');const p=this.state.product,c=p.colors[this.state.color],i=this.state.cart.find(x=>x.id===p.id&&x.size===this.state.size&&x.color===c.name),current=i?i.qty:0;if(current+this.state.qty>p.stock[this.state.size])return this.toast('Jumlah melebihi stok ukuran yang tersedia.');if(i)i.qty+=this.state.qty;else this.state.cart.push({id:p.id,size:this.state.size,color:c.name,hex:c.hex,qty:this.state.qty});this.saveCart();this.toast('Produk ditambahkan ke keranjang.');this.navigate('cart')},
