  renderCouriers(){document.getElementById('courier-options').innerHTML=StoreData.couriers.map(c=>`<label class="cursor-pointer rounded-xl border p-3 ${c.id===this.state.courier?'border-accent bg-accent/10':'border-white/10 bg-white/5'}"><input type="radio" name="courier" value="${c.id}" ${c.id===this.state.courier?'checked':''}><span class="ml-2 text-xs font-semibold">${c.name}</span><span class="mt-1 block text-xs text-zinc-400">${c.est} Â· ${this.money(c.price)}</span></label>`).join('');document.querySelectorAll('[name=courier]').forEach(r=>r.onchange=()=>{this.state.courier=r.value;this.renderCouriers();this.renderCheckout()})},
  renderCheckout(){const selected=this.state.cart.filter(i=>this.state.selectedCart.includes(this.cartKey(i)));if(!selected.length){this.toast('Pilih produk yang ingin di-checkout.');return this.navigate('cart')}this.renderCouriers();const select=document.getElementById('checkout-address');select.innerHTML=this.state.addresses.map(a=>`<option value="${this.safe(a.id)}">${this.safe(a.label)} ? ${this.safe(a.name)} ? ${this.safe(a.city)}</option>`).join('');if(!this.state.addresses.length){select.innerHTML='<option value="">Belum ada alamat tersimpan</option>';document.getElementById('checkout-address-preview').innerHTML='Tambahkan alamat penerima terlebih dahulu.';document.getElementById('ship-name').value='';document.getElementById('ship-phone').value='';document.getElementById('ship-city').value='';document.getElementById('ship-address').value=''}else{this.state.selectedAddress=this.state.addresses.some(a=>a.id===this.state.selectedAddress)?this.state.selectedAddress:this.state.addresses[0].id;localStorage.setItem('noir-selected-address',this.state.selectedAddress);select.value=this.state.selectedAddress;this.renderAddressPreview()}document.getElementById('checkout-items-list').innerHTML=selected.map(i=>{const p=StoreData.products.find(x=>x.id===i.id);return `<div class="flex items-center justify-between gap-3 text-sm"><span class="flex items-center gap-2"><img src="${p.image}" alt="" class="h-10 w-10 rounded object-cover">${this.safe(p.name)} ? ${i.qty}</span><span>${this.money(this.productPrice(p)*i.qty)}</span></div>`}).join('');const sub=this.subtotal(selected),disc=this.discount(sub),tax=Math.round((sub-disc)*.11),ship=StoreData.couriers.find(c=>c.id===this.state.courier).price;document.getElementById('checkout-subtotal').textContent=this.money(sub-disc+tax);document.getElementById('checkout-shipping').textContent=this.money(ship);document.getElementById('checkout-total').textContent=this.money(sub-disc+tax+ship);this.state.total=sub-disc+tax+ship},
