  confirmPaymentSuccess(){clearInterval(this.state.timer);if(this.state.orders.some(o=>o.id===document.getElementById('pg-order-id').textContent))return;const order={id:document.getElementById('pg-order-id').textContent,userEmail:this.state.user?.email,date:new Date().toISOString(),status:'Pembayaran selesai',total:this.state.total,items:this.state.cart.filter(i=>this.state.selectedCart.includes(this.cartKey(i))).map(i=>({...i,unitPrice:this.productPrice(StoreData.products.find(p=>p.id===i.id)||{})})),shipping:{addressId:this.state.selectedAddress,name:document.getElementById('ship-name').value,phone:document.getElementById('ship-phone').value,city:document.getElementById('ship-city').value,address:document.getElementById('ship-address').value,courier:this.state.courier}};this.state.orders.unshift(order);order.items.forEach(i=>{const p=StoreData.products.find(x=>x.id===i.id);if(p)p.stock[i.size]=Math.max(0,p.stock[i.size]-i.qty)});localStorage.setItem('noir-stock',JSON.stringify(Object.fromEntries(StoreData.products.map(p=>[p.id,p.stock]))));localStorage.setItem('noir-orders',JSON.stringify(this.state.orders));document.getElementById('pg-receipt-id').textContent=order.id;document.getElementById('pg-step-select').classList.add('hidden');document.getElementById('pg-step-success').classList.remove('hidden')},
