  renderBlockEditor(page){const list=document.getElementById('admin-'+page+'-block-list');if(!list)return;list.innerHTML=this.contentBlocks(page).map((b,i)=>'<article class="content-block-card" data-content-block="'+page+'" data-block-id="'+this.safe(b.id)+'"><header class="content-block-top"><button type="button" class="content-block-handle" draggable="true" title="Seret untuk mengatur posisi" aria-label="Geser blok">?</button><span class="content-block-name">'+this.safe(b.title||'Blok tanpa judul')+'</span><button type="button" data-block-action="remove" class="content-block-remove">Hapus blok</button></header><div class="content-block-settings"><label>Judul blok<input data-block-title value="'+this.safe(b.title||'')+'" placeholder="Contoh: Visi"></label><label>Posisi blok<select data-block-layout><option value="full" '+(b.layout==='full'?'selected':'')+'>Lebar penuh</option><option value="half" '+(b.layout!=='full'?'selected':'')+'>Setengah lebar (kiri / kanan)</option></select></label></div><div class="rich-editor-wrap">'+this.richToolbarHtml()+'<div class="rich-content" contenteditable="true" role="textbox" aria-multiline="true" data-block-body></div></div></article>').join('');list.querySelectorAll('[data-content-block]').forEach((node,i)=>{node.querySelector('[data-block-body]').innerHTML=this.richHtml(this.contentBlocks(page)[i].body)})},
