  storeContentFields(){return [['edit-hero-kicker','heroKicker'],['edit-hero-title-main','heroTitleMain'],['edit-hero-title-accent','heroTitleAccent'],['edit-hero-description','heroDescription'],['edit-hero-button-label','heroButtonLabel'],['edit-hero-note','heroNote'],['edit-hero-image-url','heroImage'],['edit-footer-about-title-edit','footerAboutTitle'],['edit-footer-about-body-edit','footerAboutBody'],['edit-footer-about-link-edit','footerAboutLink'],['edit-footer-help-title-edit','footerHelpTitle'],['edit-footer-orders-link-edit','footerOrdersLink'],['edit-footer-contact-link-edit','footerContactEmail'],['edit-footer-shipping-link-edit','footerShippingLink'],['edit-footer-terms-link-edit','footerTermsLink'],['edit-footer-social-title-edit','footerSocialTitle'],['edit-footer-instagram-edit','footerInstagram'],['edit-footer-tiktok-edit','footerTiktok'],['edit-footer-youtube-edit','footerYoutube'],['edit-footer-location-edit','footerLocation'],['edit-footer-newsletter-title-edit','footerNewsletterTitle'],['edit-footer-newsletter-body-edit','footerNewsletterBody'],['edit-footer-newsletter-placeholder-edit','footerNewsletterPlaceholder'],['edit-footer-demo-note-edit','footerDemoNote'],['edit-footer-copyright-edit','footerCopyright']]},
