  safeExternalUrl(value,fallback){try{const url=new URL(value,window.location.href);return ['https:','http:'].includes(url.protocol)?url.href:fallback}catch(_){return fallback}},
  applyStoreContent(){const c=this.state.content;[['hero-kicker','heroKicker'],['hero-title-main','heroTitleMain'],['hero-title-accent','heroTitleAccent'],['hero-description','heroDescription'],['hero-button-label','heroButtonLabel'],['hero-note','heroNote'],['footer-about-title','footerAboutTitle'],['footer-about-body','footerAboutBody'],['footer-help-title','footerHelpTitle'],['footer-orders-link','footerOrdersLink'],['footer-shipping-link','footerShippingLink'],['footer-terms-link','footerTermsLink'],['footer-social-title','footerSocialTitle'],['footer-location','footerLocation'],['footer-newsletter-title','footerNewsletterTitle'],['footer-newsletter-body','footerNewsletterBody'],['footer-demo-note','footerDemoNote'],['footer-copyright','footerCopyright']].forEach(([id,key])=>{const node=document.getElementById(id);if(node)node.textContent=c[key]});const aboutLink=document.getElementById('footer-about-link');if(aboutLink&&aboutLink.firstChild)aboutLink.firstChild.nodeValue=c.footerAboutLink+' ';const contact=document.getElementById('footer-contact-link');contact.textContent=c.footerContactEmail;contact.href='mailto:'+c.footerContactEmail;for(const [id,key,fallback] of [['footer-instagram','footerInstagram','https://instagram.com'],['footer-tiktok','footerTiktok','https://tiktok.com'],['footer-youtube','footerYoutube','https://youtube.com']])document.getElementById(id).href=this.safeExternalUrl(c[key],fallback);document.getElementById('newsletter-email').placeholder=c.footerNewsletterPlaceholder;this.renderHeroSlideshow(c.heroImages,c.heroImage)},
  async processHeroFiles(fileList){const files=Array.from(fileList||[]).filter(f=>f.type.startsWith('image/'));if(!files.length)return this.toast('Pilih file gambar terlebih dahulu.');const current=this.state.content.heroImages||[],room=Math.max(0,8-current.length);if(!room)return this.toast('Maksimal 8 foto slideshow. Hapus foto lama terlebih dahulu.');if(files.length>room)this.toast('Maksimal 8 foto. Sebagian file berikutnya tidak ditambahkan.');const selected=files.slice(0,room);try{const images=await Promise.all(selected.map(file=>this.compressHeroImage(file)));const combined=[...current,...images];if(combined.reduce((sum,image)=>sum+image.length,0)>2800000)return this.toast('Ukuran total foto terlalu besar untuk penyimpanan browser. Kurangi jumlah foto atau gunakan file yang lebih kecil.');this.state.content.heroImages=combined;this.renderHeroUploads();this.renderHeroSlideshow(this.state.content.heroImages,this.state.content.heroImage);this.toast(images.length+' foto siap. Tekan Simpan banner untuk menyimpan perubahan.')}catch(_){this.toast('Foto tidak bisa diproses. Coba gunakan file gambar lain.')}},
  compressHeroImage(file){return createImageBitmap(file).then(bitmap=>{const max=1440,scale=Math.min(1,max/Math.max(bitmap.width,bitmap.height)),canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));canvas.getContext('2d').drawImage(bitmap,0,0,canvas.width,canvas.height);bitmap.close?.();return canvas.toDataURL('image/webp',.76)})},
  renderHeroUploads(){const box=document.getElementById('hero-upload-previews');if(!box)return;const images=this.state.content.heroImages||[];box.innerHTML=images.map((src,i)=>'<article class="hero-upload-card"><img src="'+this.safe(src)+'" alt="Pratinjau foto slideshow '+(i+1)+'"><div><span>Foto '+(i+1)+'</span><button type="button" data-hero-remove="'+i+'" aria-label="Hapus foto '+(i+1)+'">Hapus</button></div></article>').join('')},
  renderHeroSlideshow(images,fallback){const valid=(Array.isArray(images)?images:[]).filter(src=>typeof src==='string'&&(src.startsWith('data:image/webp;base64,')||src.startsWith('data:image/jpeg;base64,')||src.startsWith('data:image/png;base64,')||/^https?:\/\//.test(src)||src.startsWith('assets/')));this.state.heroSlides=valid.length?valid:[this.safeExternalUrl(fallback||'assets/images/nw-03.svg','assets/images/nw-03.svg')];clearInterval(this.state.heroSlideTimer);const first=document.getElementById('hero-image'),second=document.getElementById('hero-image-next');if(!first||!second)return;this.state.heroSlideIndex=0;this.state.heroSlideActive=0;first.src=this.state.heroSlides[0];second.src=this.state.heroSlides[1%this.state.heroSlides.length];first.classList.add('opacity-100');first.classList.remove('opacity-0');second.classList.add('opacity-0');second.classList.remove('opacity-100');if(this.state.heroSlides.length<2)return;this.state.heroSlideTimer=setInterval(()=>{const incoming=this.state.heroSlideActive===0?1:0,next=(this.state.heroSlideIndex+1)%this.state.heroSlides.length,target=incoming===0?first:second,current=incoming===0?second:first;target.src=this.state.heroSlides[next];target.classList.add('opacity-100');target.classList.remove('opacity-0');current.classList.add('opacity-0');current.classList.remove('opacity-100');this.state.heroSlideIndex=next;this.state.heroSlideActive=incoming},5000)},
  saveStoreContent(){const next={...this.state.content};this.storeContentFields().forEach(([id,key])=>{const field=document.getElementById(id);next[key]=field.isContentEditable?this.richHtml(field.innerHTML):field.value.trim()});if(!next.heroTitleMain||!next.heroDescription||!next.footerAboutBody)return this.toast('Judul dan deskripsi utama tidak boleh kosong.');this.state.content=next;this.collectContentBlocks();next.heroImage=this.safeExternalUrl(next.heroImage,'assets/images/nw-03.svg');next.heroImages=this.state.content.heroImages||[];for(const key of ['footerInstagram','footerTiktok','footerYoutube'])next[key]=this.safeExternalUrl(next[key],StoreContentDefaults[key]);next.aboutBlocks=this.state.content.aboutBlocks;next.shippingBlocks=this.state.content.shippingBlocks;next.termsBlocks=this.state.content.termsBlocks;this.state.content=next;localStorage.setItem('noir-site-content',JSON.stringify(next));this.applyStoreContent();this.toast('Konten toko berhasil diperbarui.')},
