  renderAdminProducts(){const list=document.getElementById('admin-product-list');if(!list)return;list.innerHTML=StoreData.products.map(p=>`<article class="glass-panel flex items-center gap-4 rounded-xl border border-white/10 p-3"><img src="${this.safe(p.image)}" alt="" class="h-16 w-16 rounded-lg object-cover"><div class="min-w-0 flex-1"><strong class="block truncate">${this.safe(p.name)}</strong><span class="text-xs text-zinc-400">${this.money(p.price)} ? ${this.safe(p.category)}</span></div><button onclick="App.newProduct('${this.safe(p.id)}')" class="rounded-lg px-3 py-2 text-sm hover:bg-white/10">Edit</button><button onclick="App.deleteProduct('${this.safe(p.id)}')" class="rounded-lg px-3 py-2 text-sm text-red-300 hover:bg-red-500/10">Hapus</button></article>`).join('')},
