  saveProductDiscount(){const id=document.getElementById('admin-discount-product').value,percent=Number(document.getElementById('admin-discount-percent').value),p=StoreData.products.find(x=>x.id===id);if(!p||!Number.isInteger(percent)||percent<0||percent>90)return this.toast('Diskon harus 0?90 persen.');p.discountPercent=percent;localStorage.setItem('noir-products',JSON.stringify(StoreData.products));this.renderAdminPromotions();this.renderAdminProducts();this.renderProducts();this.toast(percent?'Diskon produk diperbarui.':'Diskon produk dihapus.')},
