  saveVoucher(){const old=document.getElementById('admin-voucher-original').value,code=document.getElementById('admin-voucher-code').value.trim().toUpperCase().replace(/\s+/g,''),type=document.getElementById('admin-voucher-type').value,value=Number(document.getElementById('admin-voucher-value').value),min=Math.max(0,Number(document.getElementById('admin-voucher-min').value)||0),cap=Math.max(0,Number(document.getElementById('admin-voucher-cap').value)||0);if(!/^[A-Z0-9_-]{3,24}$/.test(code))return this.toast('Kode voucher harus 3?24 karakter (huruf, angka, - atau _).');if(!Number.isFinite(value)||value<=0||(type==='percent'&&value>90))return this.toast('Nilai voucher tidak valid. Persentase maksimal 90%.');if(this.state.vouchers.some(v=>v.code===code&&code!==old))return this.toast('Kode voucher sudah digunakan.');const voucher={code,type,value,min,label:type==='percent'?'Diskon '+value+'%':'Potongan '+this.money(value),...(cap?{maxDiscount:cap}:{})};const index=this.state.vouchers.findIndex(v=>v.code===old);if(index<0)this.state.vouchers.push(voucher);else this.state.vouchers[index]=voucher;localStorage.setItem('noir-vouchers',JSON.stringify(this.state.vouchers));this.cancelVoucherEdit();this.renderAdminPromotions();this.toast('Voucher tersimpan.')},
